#!/usr/bin/env bash
# Write a CDI spec that exposes GPUs 1-3 individually as nvidia.com/gpu=gpuN.
#
# On snu-gpu, GPU 0 shows ERR! and makes NVML queries fail, so both the nvidia runtime
# (`--gpus`, "nvidia-container-cli: detection error: nvml error") and normal
# `nvidia-ctk cdi generate` ("error getting MIG mode: Unknown Error") break.
# Management mode does not query devices, so its mounts and hooks are reused here with
# one device entry per healthy GPU. Rerun after a driver update.
set -euo pipefail

GPUS="${GPUS:-1 2 3}"
OUT="${OUT:-$HOME/.config/cdi/nvidia-gpu123.yaml}"   # rootless daemon's cdi-spec-dirs
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
TMP="$WORK/management.yaml"   # nvidia-ctk writes nothing to a pre-existing file

nvidia-ctk cdi generate --mode=management --output="$TMP" >/dev/null 2>&1
mkdir -p "$(dirname "$OUT")"
python3 - "$TMP" "$OUT" $GPUS <<'EOF'
import sys
from pathlib import Path

source, output, *gpus = sys.argv[1:]
lines = Path(source).read_text().splitlines()
spec = ["# Generated by dccon-dataset experiments/env/make_cdi_spec.sh"]
spec += lines[:lines.index("devices:")] + ["devices:"]
for n in gpus:
    spec += ["- containerEdits:", "    deviceNodes:"]
    spec += [f"    - path: {path}" for path in ("/dev/nvidiactl", "/dev/nvidia-uvm",
             "/dev/nvidia-uvm-tools", "/dev/nvidia-modeset", f"/dev/nvidia{n}")]
    spec += [f"  name: gpu{n}"]
Path(output).write_text("\n".join(spec + ["kind: nvidia.com/gpu", ""]))
print(f"wrote {output}: " + ", ".join(f"nvidia.com/gpu=gpu{n}" for n in gpus))
EOF
